(() => {
  const cs = (el) => { if (!el) return null; const s = getComputedStyle(el); const r = el.getBoundingClientRect(); return { tag: el.tagName.toLowerCase(), text: (el.innerText||'').trim().slice(0,40), color: s.color, bg: s.backgroundColor, bgImg: s.backgroundImage.slice(0,120), font: s.fontFamily.slice(0,80), size: s.fontSize, weight: s.fontWeight, lh: s.lineHeight, radius: s.borderRadius, border: s.border, shadow: s.boxShadow.slice(0,100), padding: s.padding, w: Math.round(r.width), h: Math.round(r.height) }; };
  const rootVars = {};
  for (const sheet of document.styleSheets) { try { for (const rule of sheet.cssRules) { if (rule.selectorText === ':root' || rule.selectorText === 'html' || rule.selectorText === 'body') { for (const p of rule.style) if (p.startsWith('--')) rootVars[p] = rule.style.getPropertyValue(p).trim(); } } } catch (e) {} }
  const header = document.querySelector('header');
  const out = {
    title: document.title,
    rootVars: Object.fromEntries(Object.entries(rootVars).slice(0, 80)),
    body: cs(document.body),
    header: cs(header),
    headerChildren: header ? [...header.children].map(cs) : null,
    searchInput: cs(document.querySelector('header input')),
    searchForm: cs(document.querySelector('header form')),
    navLinks: [...document.querySelectorAll('header nav a, header a')].slice(0, 12).map(cs),
    h2: [...document.querySelectorAll('h2')].slice(0, 4).map(cs),
    h1: [...document.querySelectorAll('h1')].slice(0, 2).map(cs),
    buttons: [...document.querySelectorAll('button')].filter(b => b.innerText.trim()).slice(0, 10).map(cs),
    fonts: [...document.fonts].map(f => f.family + ' ' + f.weight + ' ' + f.status).slice(0, 20),
  };
  return JSON.stringify(out);
})()

